import sys, os, importlib, glob
sys.path.insert(0, '/workspace')
mods = sorted(os.path.basename(p)[:-3] for p in glob.glob('/workspace/unidecode/x*.py'))
print("module count:", len(mods))
bad = []
for m in mods:
    try:
        mod = importlib.import_module('unidecode.' + m)
    except Exception as e:
        bad.append((m, 'IMPORT FAIL: %r' % (e,)))
        continue
    if not hasattr(mod, 'data'):
        bad.append((m, 'no data attr')); continue
    d = mod.data
    if not isinstance(d, tuple):
        bad.append((m, 'data not tuple: %s' % type(d)))
    if len(d) > 256:
        bad.append((m, 'len(data)=%d > 256' % len(d)))
    for i, e in enumerate(d):
        if e is None: continue
        if not isinstance(e, str):
            bad.append((m, 'element %d (0x%02x) not str/None: %r' % (i, i, e)))
print("problems:", len(bad))
for b in bad: print("  ", b)
# also lengths distribution
import collections
print("len!=256 modules:", [(m, len(importlib.import_module('unidecode.'+m).data)) for m in mods if len(importlib.import_module('unidecode.'+m).data)!=256])
EOF
